import { Directory, File, Paths } from 'expo-file-system';
import * as Sharing from 'expo-sharing';
import { getApiBaseUrl, getAuthToken } from '@/api/client';

/**
 * Download a server-built report (xlsx | pdf) and open the phone's share sheet.
 * Reports are generated by the server so Marathi names and Indian number formats match the web app.
 */
export async function downloadReport(params: Record<string, string | number | undefined>, format: 'xlsx' | 'pdf'): Promise<void> {
  const qs = Object.entries({ ...params, format })
    .filter(([, v]) => v !== undefined && (v as unknown) !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join('&');
  const url = `${getApiBaseUrl()}/reports/export?${qs}`;

  const dir = new Directory(Paths.cache, 'reports');
  dir.create({ idempotent: true, intermediates: true });
  const task = File.createDownloadTask(url, dir, { headers: { Authorization: `Bearer ${getAuthToken() ?? ''}` } });
  const file = await task.downloadAsync();
  if (!file) throw new Error('Download was interrupted');
  if (!/\.(xlsx|pdf)$/i.test(file.name)) {
    // The server answered with an error (JSON) instead of a report
    let message = 'Export failed';
    try {
      message = JSON.parse(await file.text()).message || message;
    } catch {
      /* keep default */
    }
    try {
      file.delete();
    } catch {
      /* ignore */
    }
    throw new Error(message);
  }
  if (!(await Sharing.isAvailableAsync())) throw new Error('Sharing is not available on this device');
  await Sharing.shareAsync(file.uri, {
    mimeType: format === 'pdf' ? 'application/pdf' : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    dialogTitle: 'Share report',
  });
}
